import { useFieldContext } from '@ark-ui/solid/field';
import { useFieldsetContext } from '@ark-ui/solid/fieldset';
import {
  SegmentGroup as SegmentGroupPrimitive,
  useSegmentGroup as useSegmentGroupPrimitive,
  useSegmentGroupContext,
  useSegmentGroupItemContext,
} from '@ark-ui/solid/segment-group';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { For, splitProps } from 'solid-js';
import styles from './SegmentGroup.module.css';

type SegmentGroupMachineProps = NonNullable<Parameters<typeof useSegmentGroupPrimitive>[0]>;
type SegmentGroupOption = {
  value: string;
  label: JSX.Element;
  disabled?: boolean;
};

function omitUndefined<T extends object>(props: T) {
  return Object.fromEntries(Object.entries(props).filter(([, value]) => value !== undefined)) as T;
}

function useSegmentGroup(props?: SegmentGroupMachineProps) {
  const field = useFieldContext();
  const fieldset = useFieldsetContext();

  return useSegmentGroupPrimitive(() => {
    const machineProps = typeof props === 'function' ? props() : props;

    return omitUndefined({
      disabled: field?.()?.disabled ?? fieldset?.()?.disabled,
      invalid: field?.()?.invalid ?? fieldset?.()?.invalid,
      readOnly: field?.()?.readOnly,
      required: field?.()?.required,
      ...omitUndefined(machineProps ?? {}),
    });
  });
}

function SegmentGroupRoot(props: ComponentProps<typeof SegmentGroupPrimitive.Root>) {
  const [local, others] = splitProps(props, [
    'asChild',
    'children',
    'class',
    'defaultValue',
    'disabled',
    'form',
    'id',
    'ids',
    'invalid',
    'name',
    'onValueChange',
    'orientation',
    'readOnly',
    'required',
    'value',
  ]);

  const segmentGroup = useSegmentGroup(() =>
    omitUndefined({
      defaultValue: local.defaultValue,
      disabled: local.disabled,
      form: local.form,
      id: local.id,
      ids: local.ids,
      invalid: local.invalid,
      name: local.name,
      onValueChange: local.onValueChange,
      orientation: local.orientation ?? 'horizontal',
      readOnly: local.readOnly,
      required: local.required,
      value: local.value,
    }),
  );

  return (
    <SegmentGroupPrimitive.RootProvider
      asChild={local.asChild}
      value={segmentGroup}
      data-slot="segment-group-root"
      class={clsx(styles.root, local.class)}
      {...others}
    >
      {local.children}
    </SegmentGroupPrimitive.RootProvider>
  );
}

function SegmentGroupRootProvider(
  props: ComponentProps<typeof SegmentGroupPrimitive.RootProvider>,
) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SegmentGroupPrimitive.RootProvider
      asChild={local.asChild}
      data-slot="segment-group-root-provider"
      class={clsx(styles.root, local.class)}
      {...others}
    />
  );
}

function SegmentGroupLabel(props: ComponentProps<typeof SegmentGroupPrimitive.Label>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SegmentGroupPrimitive.Label
      asChild={local.asChild}
      data-slot="segment-group-label"
      class={clsx(styles.label, local.class)}
      {...others}
    />
  );
}

function SegmentGroupItem(props: ComponentProps<typeof SegmentGroupPrimitive.Item>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <SegmentGroupPrimitive.Item
      asChild={local.asChild}
      data-slot="segment-group-item"
      class={clsx(styles.item, local.class)}
      {...others}
    >
      {local.children}
    </SegmentGroupPrimitive.Item>
  );
}

function SegmentGroupItemControl(props: ComponentProps<typeof SegmentGroupPrimitive.ItemControl>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SegmentGroupPrimitive.ItemControl
      asChild={local.asChild}
      data-slot="segment-group-item-control"
      class={clsx(styles.itemControl, local.class)}
      {...others}
    />
  );
}

function SegmentGroupItemText(props: ComponentProps<typeof SegmentGroupPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SegmentGroupPrimitive.ItemText
      asChild={local.asChild}
      data-slot="segment-group-item-text"
      class={clsx(styles.itemText, local.class)}
      {...others}
    />
  );
}

function SegmentGroupIndicator(props: ComponentProps<typeof SegmentGroupPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SegmentGroupPrimitive.Indicator
      asChild={local.asChild}
      data-slot="segment-group-indicator"
      class={clsx(styles.indicator, local.class)}
      {...others}
    />
  );
}

function SegmentGroupItems(props: { items: readonly SegmentGroupOption[] }) {
  return (
    <For each={props.items}>
      {(item) => (
        <SegmentGroupItem value={item.value} disabled={item.disabled}>
          <SegmentGroupItemText>{item.label}</SegmentGroupItemText>
          <SegmentGroupItemControl />
          <SegmentGroupPrimitive.ItemHiddenInput />
        </SegmentGroupItem>
      )}
    </For>
  );
}

const SegmentGroup = Object.assign(SegmentGroupRoot, {
  Root: SegmentGroupRoot,
  RootProvider: SegmentGroupRootProvider,
  Context: SegmentGroupPrimitive.Context,
  ItemContext: SegmentGroupPrimitive.ItemContext,
  Label: SegmentGroupLabel,
  Item: SegmentGroupItem,
  ItemHiddenInput: SegmentGroupPrimitive.ItemHiddenInput,
  ItemControl: SegmentGroupItemControl,
  ItemText: SegmentGroupItemText,
  Indicator: SegmentGroupIndicator,
  Items: SegmentGroupItems,
});

export { SegmentGroup, useSegmentGroup, useSegmentGroupContext, useSegmentGroupItemContext };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    position: relative;
    isolation: isolate;
    display: inline-flex;
    max-inline-size: var(--moduix-segment-group-max-width, 100%);
    align-items: stretch;
    gap: var(--moduix-segment-group-gap, var(--moduix-spacing-1));
    padding: var(--moduix-segment-group-padding, var(--moduix-spacing-1));
    border: var(--moduix-segment-group-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-segment-group-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-segment-group-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-segment-group-bg, var(--moduix-color-muted));
    color: var(--moduix-segment-group-color, var(--moduix-color-foreground));

    &[data-orientation='vertical'] {
      flex-direction: column;
      align-items: stretch;
    }

    &[data-disabled] {
      opacity: var(--moduix-segment-group-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &:not([data-disabled]) {
      .item[data-disabled] {
        opacity: var(--moduix-segment-group-item-disabled-opacity, var(--moduix-opacity-disabled));
      }
    }

    &[data-invalid] {
      border-color: var(
        --moduix-segment-group-border-color-invalid,
        var(--moduix-color-destructive)
      );
    }
  }

  .label {
    position: relative;
    z-index: 1;
    color: var(
      --moduix-segment-group-label-color,
      var(--moduix-segment-group-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-segment-group-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-segment-group-label-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-segment-group-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  .item {
    box-sizing: border-box;
    position: relative;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-segment-group-item-gap, var(--moduix-spacing-2));
    min-height: var(--moduix-segment-group-item-height, var(--moduix-size-sm));
    border-radius: var(--moduix-segment-group-item-radius, var(--moduix-radius-md));
    padding-inline: var(--moduix-segment-group-item-padding-x, var(--moduix-spacing-3-5));
    color: var(--moduix-segment-group-item-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-segment-group-item-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-segment-group-item-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-segment-group-item-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
    white-space: nowrap;
    cursor: pointer;
    outline: 0;
    transition:
      color var(--moduix-segment-group-transition, var(--moduix-transition-default)),
      opacity var(--moduix-segment-group-transition, var(--moduix-transition-default));

    @media (hover: hover) {
      &:hover:not([data-readonly], [data-disabled]) {
        color: var(--moduix-segment-group-item-color-hover, var(--moduix-color-foreground));

        &[data-state='checked'] {
          color: var(
            --moduix-segment-group-item-color-hover,
            var(--moduix-segment-group-item-color-checked, var(--moduix-color-foreground))
          );
        }
      }
    }

    &[data-state='checked'] {
      color: var(--moduix-segment-group-item-color-checked, var(--moduix-color-foreground));
    }

    &[data-focus-visible] {
      outline: var(
          --moduix-segment-group-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-segment-group-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-segment-group-focus-ring-offset, var(--moduix-border-width-sm));
    }

    &[data-invalid][data-focus-visible] {
      outline-color: var(
        --moduix-segment-group-focus-ring-color-invalid,
        var(--moduix-color-destructive)
      );
    }

    &[data-readonly],
    &[data-disabled] {
      cursor: default;
    }

    &[data-orientation='vertical'] {
      inline-size: 100%;
      justify-content: flex-start;
    }
  }

  .itemControl {
    display: none;
  }

  .itemText {
    position: relative;
    z-index: 1;
  }

  .indicator {
    --transition-duration: var(
      --moduix-segment-group-indicator-transition-duration,
      var(--moduix-duration-normal)
    );
    --transition-timing-function: var(
      --moduix-segment-group-indicator-transition-timing-function,
      var(--moduix-ease-in-out)
    );

    position: absolute;
    z-index: 0;
    top: var(--top);
    left: var(--left);
    width: var(--width);
    height: var(--height);
    border-radius: var(--moduix-segment-group-indicator-radius, var(--moduix-radius-md));
    background-color: var(--moduix-segment-group-indicator-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-segment-group-indicator-shadow, var(--moduix-shadow-sm));
    pointer-events: none;
  }
}

export {
  SegmentGroup,
  useSegmentGroup,
  useSegmentGroupContext,
  useSegmentGroupItemContext,
} from './SegmentGroup.js';
